<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Listener;

use Civi\Lughauth\Features\Document\Rendering\Application\Service\DocumentAssetDumpService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetDeleteEvent;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetEvent;

/**
 * Keeps the local .assets/themes/ directory in sync with the database.
 *
 * Registered for ThemeAssetEvent so it handles all sub-events (Create, Update,
 * Enable, Disable, Delete) via a single listener entry.
 *
 * - Delete  → remove the file from disk (blob already gone from storage).
 * - Others  → write to disk when enabled; remove when disabled.
 */
class ThemeAssetDiskSyncListener
{
    public function __construct(
        private readonly DocumentAssetDumpService $assetDumpService,
    ) {
    }

    public function __invoke(ThemeAssetEvent $event): void
    {
        if ($event instanceof ThemeAssetDeleteEvent) {
            $this->assetDumpService->removeThemeAsset($event->payload);
        } else {
            $this->assetDumpService->dumpThemeAsset($event->payload);
        }
    }
}
